def main():
    print(f"MRCP Topics Count: {len(MRCP_TOPICS)}")
    print(f"FCPS Topics Count: {len(FCPS_TOPICS)}")
    print(f"NLE Topics Count: {len(NLE_TOPICS)}")
    
    assert len(MRCP_TOPICS) == 100, f"Expected 100 MRCP topics, got {len(MRCP_TOPICS)}"
    assert len(FCPS_TOPICS) == 100, f"Expected 100 FCPS topics, got {len(FCPS_TOPICS)}"
    assert len(NLE_TOPICS) == 100, f"Expected 100 NLE topics, got {len(NLE_TOPICS)}"
    
    for i, t in enumerate(MRCP_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at MRCP #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at MRCP #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at MRCP #{i}: {t[5]}"
        
    for i, t in enumerate(FCPS_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at FCPS #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at FCPS #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at FCPS #{i}: {t[5]}"
        
    for i, t in enumerate(NLE_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at NLE #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at NLE #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at NLE #{i}: {t[5]}"
        
    out_path = os.path.join(os.path.dirname(__file__), "mega95_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 95 Part B topics (MRCP 100, FCPS 100, NLE 100)\n\n")
        f.write(f"MRCP_TOPICS = {json.dumps(MRCP_TOPICS, indent=2)}\n\n")
        f.write(f"FCPS_TOPICS = {json.dumps(FCPS_TOPICS, indent=2)}\n\n")
        f.write(f"NLE_TOPICS = {json.dumps(NLE_TOPICS, indent=2)}\n")
        
    print(f"Saved Part B topics to {out_path}!")

if __name__ == "__main__":
    main()
